+package pir
+
+import (
+	"encoding/binary"
+	"math/bits"
+
+	"easypir/safeaes"
+	"example.com/util"
+)
+
+func blockKey(master *safeaes.RoundKeys, tag uint32, block uint64) (key [16]byte) {
+	var input [16]byte
+	binary.LittleEndian.PutUint64(input[:], uint64(tag)<<35+block)
+	safeaes.MMO(master, &key, &input)
+	return
+}
+
+func apply(key *safeaes.RoundKeys, position uint64) uint64 {
+	var in, out [16]byte
+	binary.LittleEndian.PutUint64(in[:], position)
+	safeaes.MMO(key, &out, &in)
+	return binary.LittleEndian.Uint64(out[:])
+}
+
+// A block number is a field element. Use GF(2^16) independently on
+// the eight 16-bit components of an entry, with modulus 0x1100b.
+func timesX(word uint64) uint64 {
+	const msb = 0x8000800080008000
+	return (word&^msb)<<1 ^ ((word&msb)>>15)*0x100b
+}
+
+func scale(v util.DBEntry, coefficient uint64) (product util.DBEntry) {
+	if coefficient == 1 {
+		return v
+	}
+	for coefficient != 0 {
+		if coefficient&1 != 0 {
+			product[0] ^= v[0]
+			product[1] ^= v[1]
+		}
+		coefficient >>= 1
+		v[0] = timesX(v[0])
+		v[1] = timesX(v[1])
+	}
+	return
+}
+
+func inverse(coefficient uint64) uint64 {
+	// Extended Euclid on binary polynomials.
+	a, b := coefficient, uint64(0x1100b)
+	u, v := uint64(1), uint64(0)
+	for a != 1 {
+		if a < b {
+			a, b = b, a
+			u, v = v, u
+		}
+		shift := bits.Len64(a) - bits.Len64(b)
+		a ^= b << shift
+		u ^= v << shift
+	}
+	return u
+}
+
+func xor(a, b util.DBEntry) util.DBEntry {
+	return util.DBEntry{a[0] ^ b[0], a[1] ^ b[1]}
+}
+
+func getEntry(buf []byte) util.DBEntry {
+	return util.DBEntry{binary.LittleEndian.Uint64(buf), binary.LittleEndian.Uint64(buf[8:])}
+}
+
+func putEntry(buf []byte, e util.DBEntry) {
+	binary.LittleEndian.PutUint64(buf, e[0])
+	binary.LittleEndian.PutUint64(buf[8:], e[1])
+}
+
+// Keep the independent input blocks in flight under the same expanded key.
+func encryptEight(key *safeaes.RoundKeys, out, in *[8][16]byte) {
+	safeaes.Encrypt(key, &out[0], &in[0])
+	safeaes.Encrypt(key, &out[1], &in[1])
+	safeaes.Encrypt(key, &out[2], &in[2])
+	safeaes.Encrypt(key, &out[3], &in[3])
+	safeaes.Encrypt(key, &out[4], &in[4])
+	safeaes.Encrypt(key, &out[5], &in[5])
+	safeaes.Encrypt(key, &out[6], &in[6])
+	safeaes.Encrypt(key, &out[7], &in[7])
+}
