+)
+
+func keyFromWords(a, b uint64) (key [16]byte) {
+	binary.LittleEndian.PutUint64(key[:], a)
+	binary.LittleEndian.PutUint64(key[8:], b)
+	return
+}
+
+// Keep unread draws when a parallel rejection search succeeds partway
+// through a batch.
+type coinStream struct {
+	source rand.Source64
+	words  []uint64
+	pos    int
+}
+
+// The Source64 used by math/rand has a lagged additive recurrence. Seed
+// its window from the actual source, then compute contiguous spans without
+// a virtual call and two circular indices on every rejection draw.
+const streamLag = 607
+
+func (s *coinStream) prepare() {
+	s.words = make([]uint64, 32768+streamLag)
+	for i := 0; i < streamLag; i++ {
+		s.words[i] = s.source.Uint64()
+	}
+	s.expand()
+	s.pos = 0
+	s.source = nil
+}
+
+func (s *coinStream) expand() {
+	for i := streamLag; i < len(s.words); i++ {
+		s.words[i] = s.words[i-streamLag] + s.words[i-273]
+	}
+}
+
+func (s *coinStream) fill() {
+	start := len(s.words) - streamLag
+	copy(s.words[:streamLag], s.words[start:])
+	s.pos -= start
+	s.expand()
+}
+
+func (s *coinStream) next() uint64 {
+	if s.pos == len(s.words) {
+		s.fill()
+	}
+	v := s.words[s.pos]
+	s.pos++
+	return v
+}
+
+func (s *coinStream) pairs() []uint64 {
+	if len(s.words)-s.pos < 2 {
+		s.fill()
+	}
+	return s.words[s.pos:]
+}
+
+func (c *Client) workers() int {
+	if c.p.ChunkSize < 2048 {
+		return 1
+	}
+	return int(c.p.Threads)
+}
+
+const searchBatch = 8
+
+type searchBuffers struct {
+	input       [searchBatch][16]byte
+	raw, output [searchBatch][16]byte
+	expanded    [searchBatch]safeaes.RoundKeys
+}
