+// Stage the eight independent key expansions before their encryptions.
+func (s *searchBuffers) evaluate(rel uint64) {
+	safeaes.ExpandKey(&s.raw[0], &s.expanded[0])
+	safeaes.ExpandKey(&s.raw[1], &s.expanded[1])
+	safeaes.ExpandKey(&s.raw[2], &s.expanded[2])
+	safeaes.ExpandKey(&s.raw[3], &s.expanded[3])
+	safeaes.ExpandKey(&s.raw[4], &s.expanded[4])
+	safeaes.ExpandKey(&s.raw[5], &s.expanded[5])
+	safeaes.ExpandKey(&s.raw[6], &s.expanded[6])
+	safeaes.ExpandKey(&s.raw[7], &s.expanded[7])
+	var block [16]byte
+	binary.LittleEndian.PutUint64(block[:], rel)
+	safeaes.Encrypt(&s.expanded[0], &s.output[0], &block)
+	safeaes.Encrypt(&s.expanded[1], &s.output[1], &block)
+	safeaes.Encrypt(&s.expanded[2], &s.output[2], &block)
+	safeaes.Encrypt(&s.expanded[3], &s.output[3], &block)
+	safeaes.Encrypt(&s.expanded[4], &s.output[4], &block)
+	safeaes.Encrypt(&s.expanded[5], &s.output[5], &block)
+	safeaes.Encrypt(&s.expanded[6], &s.output[6], &block)
+	safeaes.Encrypt(&s.expanded[7], &s.output[7], &block)
+}
+
+// Claim ranges in ascending order. Once a match is found, only outstanding
+// earlier ranges can improve it. This also balances lanes with different
+// scheduling delays.
+func (c *Client) firstMatch(count int, match func(int, int, *searchBuffers) int) int {
+	workers := len(c.search)
+	if workers == 1 || count < 256 {
+		return match(0, count, &c.search[0])
+	}
+	best := uint64(count)
+	var wg sync.WaitGroup
+	const stripe = 128
+	var next uint64
+	run := func(lane int) {
+		for {
+			start := int(atomic.AddUint64(&next, stripe) - stripe)
+			if start >= int(atomic.LoadUint64(&best)) {
+				break
+			}
+			end := start + stripe
+			if end > count {
+				end = count
+			}
+			i := match(start, end, &c.search[lane])
+			if i < end {
+				for {
+					old := atomic.LoadUint64(&best)
+					if uint64(i) >= old || atomic.CompareAndSwapUint64(&best, old, uint64(i)) {
+						break
+					}
+				}
+				break
+			}
+		}
+	}
+	wg.Add(workers - 1)
+	for i := 1; i < workers; i++ {
+		go func(lane int) { run(lane); wg.Done() }(i)
+	}
+	run(0)
+	wg.Wait()
+	return int(best)
+}
