+}
+
+func gather(db []uint64, indices []int) util.DBEntry {
+	var a, b uint64
+	for len(indices) >= 4 {
+		i, j, k, l := indices[0], indices[1], indices[2], indices[3]
+		a ^= db[i] ^ db[j] ^ db[k] ^ db[l]
+		b ^= db[i+1] ^ db[j+1] ^ db[k+1] ^ db[l+1]
+		indices = indices[4:]
+	}
+	for _, v := range indices {
+		a ^= db[v]
+		b ^= db[v+1]
+	}
+	return util.DBEntry{a, b}
 }
